model=#{changes.model}, prompt_tokens=#{changes.prompt_tokens}, completion_tokens=#{changes.completion_tokens}, total_tokens=#{changes.total_tokens}, cost=#{changes.cost}, status=#{changes.status}, completed_at=#{changes.completed_at}, latency_ms=#{changes.latency_ms},
WHERE id=#{conversation_id}
